const promQuery = `
label_replace(100 * (1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes), "metric", "memory_pct", "", "")
or label_replace(node_load1, "metric", "load1", "", "")
or label_replace(count(node_cpu_seconds_total{mode="idle"}), "metric", "cpu_count", "", "")
or label_replace(100 * (1 - node_filesystem_avail_bytes{mountpoint=~"^(/|/raid5pool)$"} / node_filesystem_size_bytes{mountpoint=~"^(/|/raid5pool)$"}), "metric", "disk_pct", "", "")
or label_replace(sum(node_systemd_unit_state{state="failed"}), "metric", "failed_units", "", "")
or label_replace(zfs_pool_health, "metric", "zfs_health", "", "")
or label_replace(smartctl_device_smart_status, "metric", "smart_status", "", "")
`;

const prom = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8451/api/v1/query',
  qs: { query: promQuery },
  json: true,
});

const series = prom?.data?.result ?? [];
const byMetric = (name) => series.filter((s) => s.metric.metric === name);
const value = (s) => Number(s.value[1]);

const memoryPct = value(byMetric('memory_pct')[0]);
const load1 = value(byMetric('load1')[0]);
const cpuCount = value(byMetric('cpu_count')[0]);
const failedUnits = value(byMetric('failed_units')[0]);

const disks = byMetric('disk_pct').map((s) => ({ mountpoint: s.metric.mountpoint, pct: value(s) }));
const zfsPools = byMetric('zfs_health').map((s) => ({ pool: s.metric.pool, healthy: value(s) === 0 }));
const smartDevices = byMetric('smart_status').map((s) => ({ device: s.metric.device, healthy: value(s) === 1 }));

// Gatus already alerts on failure by itself -- this section only adds a status
// summary to the digest, so a Gatus outage degrades the email, not the run.
let gatus = [];
try {
  gatus = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://127.0.0.1:8494/api/v1/endpoints/statuses',
    json: true,
  });
} catch (error) {
  gatus = [];
}

const services = gatus.map((endpoint) => {
  const last = endpoint.results?.[endpoint.results.length - 1];
  return { name: endpoint.name, up: last?.success ?? false };
});

const loadRatio = cpuCount ? load1 / cpuCount : 0;
const status = (v, warn, critical) => (v >= critical ? 'critical' : v >= warn ? 'warn' : 'ok');

const rows = [
  {
    label: 'cpu_load',
    value: `${load1.toFixed(2)}`,
    detail: `${(loadRatio * 100).toFixed(0)}% of ${cpuCount} cores`,
    level: status(loadRatio, 0.7, 1.0),
  },
  { label: 'memory', value: `${memoryPct.toFixed(1)}%`, detail: '', level: status(memoryPct, 80, 90) },
  ...disks.map((d) => ({
    label: `disk ${d.mountpoint}`,
    value: `${d.pct.toFixed(1)}%`,
    detail: '',
    level: status(d.pct, 80, 90),
  })),
  {
    label: 'failed_units',
    value: String(failedUnits),
    detail: '',
    level: failedUnits > 0 ? 'critical' : 'ok',
  },
  ...zfsPools.map((p) => ({
    label: `zpool ${p.pool}`,
    value: p.healthy ? 'ONLINE' : 'NOT ONLINE',
    detail: '',
    level: p.healthy ? 'ok' : 'critical',
  })),
  ...smartDevices.map((d) => ({
    label: `smart ${d.device}`,
    value: d.healthy ? 'PASSED' : 'FAILED',
    detail: '',
    level: d.healthy ? 'ok' : 'critical',
  })),
];

const overall = rows.some((r) => r.level === 'critical') ? 'critical' : rows.some((r) => r.level === 'warn') ? 'warn' : 'ok';

// {{{ Rosé Pine Moon
// The one palette every digest from this instance now uses, lifted from the
// same base16 scheme as the desktops (`rose-pine-moon.yaml` in
// base16-schemes, via common/themes/default.nix). Duplicated into each Code
// node because n8n Code nodes cannot import -- if you change a value here,
// change it in the other four.
//
// Status meaning is fixed across all of them: foam is fine, gold wants a
// look, love wants an action. Only the layout and the type change per digest.
const rp = {
  base: '#232136',
  surface: '#2a273f',
  overlay: '#393552',
  muted: '#6e6a86',
  subtle: '#908caa',
  text: '#e0def4',
  love: '#eb6f92',
  gold: '#f6c177',
  rose: '#ea9a97',
  pine: '#3e8fb0',
  foam: '#9ccfd8',
  iris: '#c4a7e7',
  highlight: '#56526e',
};

const level = {ok: rp.foam, warn: rp.gold, critical: rp.love};
const tag = {ok: '[ OK ]', warn: '[WARN]', critical: '[CRIT]'};
const overallCopy = {
  ok: 'ALL SYSTEMS NOMINAL',
  warn: 'ATTENTION REQUIRED',
  critical: 'ACTION REQUIRED',
}[overall];
const mono = "ui-monospace,'JetBrains Mono','SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace";
const accent = level[overall];
// }}}

// {{{ Render
// A bar drawn out of table cells rather than a background image or a unicode
// block run: Outlook drops the former and renders the latter at the wrong
// width in half its versions. Two cells and a border always work.
const gauge = (pct, colour) => {
  const filled = Math.max(2, Math.min(100, Math.round(pct)));
  return `<table role="presentation" width="100%" style="border-collapse:collapse;table-layout:fixed;">
    <tr>
      <td width="${filled}%" style="height:3px;line-height:3px;font-size:0;background:${colour};">&nbsp;</td>
      <td width="${100 - filled}%" style="height:3px;line-height:3px;font-size:0;background:${rp.overlay};">&nbsp;</td>
    </tr>
  </table>`;
};

const metricRow = (r) => {
  const c = level[r.level];
  return `<tr>
    <td style="padding:11px 30px 4px 30px;">
      <table role="presentation" width="100%" style="border-collapse:collapse;">
        <tr>
          <td style="font-family:${mono};font-size:13px;color:${rp.subtle};white-space:nowrap;">${r.label}</td>
          <td style="font-family:${mono};font-size:13px;color:${rp.text};text-align:right;white-space:nowrap;">
            ${r.value}${r.detail ? `<span style="color:${rp.muted};font-size:11px;"> ${r.detail}</span>` : ''}
            <span style="color:${c};font-weight:700;margin-left:12px;">${tag[r.level]}</span>
          </td>
        </tr>
      </table>
    </td>
  </tr>
  <tr><td style="padding:0 30px 9px 30px;">${
    r.pct === null
      ? `<div style="border-top:1px solid ${rp.overlay};"></div>`
      : gauge(r.pct, c)
  }</td></tr>`;
};

// Only things that are genuinely a proportion get a bar. A full-width bar
// under "zpool ONLINE" or "smart PASSED" looks like a meter pinned at 100%,
// which is a measurement the digest never made -- those rows get a hairline
// instead. cpu_load is the awkward case: its value is a load average, but its
// detail carries the percentage of cores that actually means something.
const percentOf = (r) => {
  const direct = /^([\d.]+)%$/.exec(r.value);
  if (direct) return Number(direct[1]);
  const fromDetail = /([\d.]+)% of/.exec(r.detail ?? '');
  return fromDetail ? Number(fromDetail[1]) : null;
};

const rowsHtml = rows.map((r) => metricRow({...r, pct: percentOf(r)})).join('\n');

const servicesHtml = services.length
  ? `<tr><td style="padding:2px 30px 18px 30px;">
      <table role="presentation" width="100%" style="border-collapse:collapse;">
        ${services
          .map((s, i) => {
            const c = s.up ? rp.foam : rp.love;
            // Two per row: forty endpoints as forty full-width lines is a
            // scroll, not a status.
            const open = i % 2 === 0 ? '<tr>' : '';
            const close = i % 2 === 1 || i === services.length - 1 ? '</tr>' : '';
            return `${open}<td width="50%" style="padding:4px 10px 4px 0;font-family:${mono};font-size:12px;color:${rp.subtle};white-space:nowrap;overflow:hidden;">
              <span style="color:${c};font-weight:700;">${s.up ? '●' : '○'}</span>&nbsp; ${s.name}
            </td>${close}`;
          })
          .join('')}
      </table>
    </td></tr>`
  : `<tr><td style="padding:6px 30px 18px 30px;font-family:${mono};font-size:12px;color:${rp.muted};">gatus returned no data.</td></tr>`;

const timestamp = new Date().toLocaleString('de-DE', {timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short'});

const section = (title, note) => `<tr>
  <td style="padding:20px 30px 2px 30px;">
    <table role="presentation" width="100%" style="border-collapse:collapse;">
      <tr>
        <td style="font-family:${mono};font-size:11px;letter-spacing:0.18em;color:${rp.iris};text-transform:uppercase;white-space:nowrap;">${title}</td>
        <td style="font-family:${mono};font-size:10px;color:${rp.muted};text-align:right;white-space:nowrap;">${note}</td>
      </tr>
    </table>
    <div style="border-top:1px solid ${rp.overlay};margin-top:8px;"></div>
  </td>
</tr>`;

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:30px 14px;background:${rp.base};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;border-collapse:collapse;">
      <tr>
        <td style="background:${rp.surface};border:1px solid ${rp.overlay};border-radius:8px;overflow:hidden;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td style="height:3px;line-height:3px;font-size:0;background:${accent};">&nbsp;</td></tr>
            <tr>
              <td style="padding:26px 30px 6px 30px;">
                <div style="font-family:${mono};font-size:11px;color:${rp.pine};">$ ssh inari &amp;&amp; health-check --daily</div>
                <div style="font-family:${mono};font-size:22px;font-weight:700;letter-spacing:0.05em;color:${rp.text};margin-top:14px;">HEALTH_MONITOR</div>
                <div style="font-family:${mono};font-size:13px;font-weight:700;color:${accent};margin-top:9px;">${tag[overall]} ${overallCopy}</div>
                <div style="font-family:${mono};font-size:11px;color:${rp.muted};margin-top:9px;">${timestamp} &middot; inari</div>
              </td>
            </tr>
            ${section('system metrics', `${rows.length} checks`)}
            ${rowsHtml}
            ${section('service status', `${services.filter((s) => s.up).length}/${services.length} up &middot; gatus`)}
            ${servicesHtml}
            <tr><td style="border-top:1px solid ${rp.overlay};"></td></tr>
            <tr><td style="padding:14px 30px;font-family:${mono};font-size:10px;color:${rp.muted};">generated by n8n @ inari &middot; rosé pine moon</td></tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

return [{json: {subject: `[inari] ${tag[overall]} ${overallCopy}`, html}}];
